public class StripePainterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static java.awt.image.BufferedImage render(int width, int height, int stripes) {
        java.awt.image.BufferedImage img =
                new java.awt.image.BufferedImage(width, height, java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = img.createGraphics();
        try {
            StripePainter.paint(g, width, height, stripes);
        } finally {
            g.dispose();
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage a = render(80, 40, 4);
            check("4 stripes: stripe 0 center is black (10,20)", "#000000", pixel(a, 10, 20));
            check("4 stripes: stripe 1 center is white (30,20)", "#FFFFFF", pixel(a, 30, 20));
            check("4 stripes: stripe 2 center is black (50,20)", "#000000", pixel(a, 50, 20));
            check("4 stripes: stripe covers full height (30,5)", "#FFFFFF", pixel(a, 30, 5));
            java.awt.image.BufferedImage b = render(80, 60, 8);
            check("8 stripes: stripe 2 center is black (25,30)", "#000000", pixel(b, 25, 30));
            check("8 stripes: stripe 3 center is white (35,30)", "#FFFFFF", pixel(b, 35, 30));
            check("8 stripes: stripe 6 center is black (65,30)", "#000000", pixel(b, 65, 30));
            check("8 stripes: stripe 7 center is white (75,30)", "#FFFFFF", pixel(b, 75, 30));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

