import java.awt.Color;
import java.awt.Graphics2D;

public class StripePainter {

    public static void paint(Graphics2D g, int width, int height, int stripes) {
        int stripeWidth = width / stripes;
        for (int i = 0; i < stripes; i++) {
            g.setColor(i % 2 == 0 ? Color.BLACK : Color.WHITE);
            g.fillRect(i * stripeWidth, 0, stripeWidth, height);
        }
    }
}
